---@type Singleton
local Singleton = import('Frame.Singleton')
local BattleHelperVo = import("Game.Setting.Vo.BattleHelperVo")

---@class BattleHelperConfMgr : Singleton
---@field GetInstance fun(self:BattleHelperConfMgr):BattleHelperConfMgr
local BattleHelperConfMgr = Class("BattleHelperConfMgr", Singleton)

function BattleHelperConfMgr:__init()
end

function BattleHelperConfMgr:__delete()
end

--[[
    @desc: 获取一个主线的机器人  !!!主线队伍用
    author:{author}
    time:2020-07-13 14:02:53
    --@teamId: 阵容id
	--@cardId: 
    @return: 返回一个机器人数据
]]
function BattleHelperConfMgr:GetMainLevelHelper(teamId, cardId)
    ---@type BattleHelperVo
    local helperVo

    ---@type BattleHelperTeamVo
    local teamVo = CfUtils.GetCfVo(AutoIds.IdSetting721, "BattleHelperTeamVo", teamId)
    --如果没有这个阵容id 直接返回
    if not teamVo then
        return helperVo
    end

    local idsV = CfUtils.Split(checkString(teamVo.lineupId))  --所有的卡牌ID  
    local possV = CfUtils.Split(checkString(teamVo.Station))  --队伍位置
    local equipGroupsIdV = CfUtils.Split(checkString(teamVo.equipId))  --所有的装备组
    local cardSkin = CfUtils.Split(checkString(teamVo.cardSkin))  --所有皮肤id
    local relationLineupId = CfUtils.Split(checkString(teamVo.relationLineupId))  --所有羁绊id

    local index = 0   --表里是4个数据一配， 用来标识取第几个数据
    for k, v in pairs(idsV) do
        if checkNumber(v) == checkNumber(cardId) then
            helperVo = BattleHelperVo:New()
            index = checkNumber(k)
            helperVo:FillCardId(cardId)
        end
    end
    --如果没有这个id 直接返回nil
    if not helperVo then
        return helperVo
    end
    helperVo.fettersId = checkNumber(relationLineupId[index])
    helperVo.fettersCardId = checkNumber(relationLineupId[index])

    --填充一下队伍位置
    helperVo:FillTeamPosition(checkNumber(possV[index]))
    local equipsGroupId = equipGroupsIdV[index]      --装备组

    --如果这个卡牌带了装备
    if equipsGroupId then
        ---@type BattleHelperEquipVo
        local equipVo = CfUtils.GetCfVo(AutoIds.IdSetting722, "BattleHelperEquipVo", equipsGroupId)
        --如果有这组装备
        if equipVo then
            local equipGoodsIds = equipVo:GetEquipGoodsIds()
            helperVo:FillEquip(equipGoodsIds)
        end
    end

    --卡牌基础属性 等级这些
    ---@type BattleHelperAttrVo
    local basicsInfoVo = CfUtils.GetCfVo(AutoIds.IdSetting720, "BattleHelperAttrVo", teamId)
    if basicsInfoVo then
        helperVo:FillBasicsInfo(basicsInfoVo, index, cardSkin[index])
    end

    return helperVo
end

---是否限制猫球使用（主线机器人关卡才会出现）
function BattleHelperConfMgr:IsCatBallLimit(curLevelId)
    local questVo = QuestConfMgr:GetInstance():GetQuestVoById(curLevelId)
    if not questVo then return false end
    
    local basicsInfoVo = CfUtils.GetCfVo(AutoIds.IdSetting721, "BattleHelperTeamVo", questVo.petLineup)
    local a = CfUtils.GetCf(AutoIds.IdSetting720, "BattleHelperAttrVo", true)
    if not basicsInfoVo then return false end
    
    return checkInt(basicsInfoVo.catBall) == 1
end


return BattleHelperConfMgr
